def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    if n < 4:
        od = 0
        for _, b in history:
            if b == 'D':
                od += 1
        if od == n or (n == 3 and od >= 2):
            return 'D'
        return 'C'

    od_total = 0
    my_d_total = 0
    for a, b in history:
        if a == 'D':
            my_d_total += 1
        if b == 'D':
            od_total += 1

    od10 = 0
    for _, b in history[-10:]:
        if b == 'D':
            od10 += 1

    if od_total == n or od10 >= 8:
        return 'D'
    if all(b == 'D' for _, b in history[-4:]):
        return 'D'

    start_rec = max(1, n - 30)
    punish_tot = 0
    punish_def_tot = 0
    unprov_tot = 0
    unprov_def_tot = 0
    punish_rec = 0
    punish_def_rec = 0
    unprov_rec = 0
    unprov_def_rec = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        co = history[i][1]
        rec = i >= start_rec
        if pm == 'D':
            punish_tot += 1
            if co == 'D':
                punish_def_tot += 1
            if rec:
                punish_rec += 1
                if co == 'D':
                    punish_def_rec += 1
        else:
            unprov_tot += 1
            if co == 'D':
                unprov_def_tot += 1
            if rec:
                unprov_rec += 1
                if co == 'D':
                    unprov_def_rec += 1

    if punish_rec:
        p_rate = float(punish_def_rec) / float(punish_rec)
    elif punish_tot:
        p_rate = float(punish_def_tot) / float(punish_tot)
    else:
        p_rate = 0.0

    if unprov_rec:
        u_rate = float(unprov_def_rec) / float(unprov_rec)
    elif unprov_tot:
        u_rate = float(unprov_def_tot) / float(unprov_tot)
    else:
        u_rate = 0.0

    if u_rate > 0.5 and od_total > 3:
        return 'D'

    if opp_last == 'D':
        streak = 0
        for _, b in reversed(history):
            if b == 'D':
                streak += 1
            else:
                break

        if streak >= 4 or od10 >= 7 or u_rate > 0.4:
            return 'D'
        if n >= 90 and streak >= 2:
            return 'D'
        if streak >= 2 and u_rate > 0.15 and od_total > 2:
            return 'D'
        if p_rate > 0.75 and od_total <= max(4, n // 2):
            return 'C'
        if od_total <= max(3, n // 4) and u_rate < 0.25 and my_d_total <= od_total + 3:
            return 'C'
        if od_total <= max(5, n // 3) and od10 <= 2 and my_d_total <= od_total + 2:
            return 'C'
        if od_total <= 2 and streak == 1:
            return 'C'
        if od10 >= 5 or od_total * 3 > n:
            return 'D'
        return 'D'

    if p_rate > 0.75 and u_rate < 0.3 and od_total <= max(4, n // 2):
        return 'C'

    toler = 0
    for k in range(n - 1, -1, -1):
        if history[k][0] == 'D' and history[k][1] == 'C':
            toler += 1
        else:
            break

    if toler >= 2 and od10 <= 2 and u_rate < 0.35:
        if p_rate < 0.55 or toler >= 5:
            return 'D'

    if my_last == 'D' and punish_tot == 0 and n < 80:
        return 'C'

    if od10 == 0 and od_total <= max(2, n // 8) and u_rate < 0.35:
        return 'D'

    if od10 <= 1 and od_total <= max(3, n // 5) and u_rate < 0.30 and p_rate < 0.25:
        return 'D'

    if od10 <= 2 and od_total <= max(5, n // 4) and u_rate < 0.20 and p_rate < 0.18:
        return 'D'

    if n >= 95 and od10 <= 2 and u_rate < 0.30 and p_rate < 0.40 and my_d_total <= od_total + 6:
        return 'D'

    if od10 >= 6:
        return 'D'
    if od10 >= 4 and u_rate > 0.30:
        return 'D'
    if my_d_total > od_total + 6:
        return 'C'

    return 'C'
